INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('baeume-aeussere-mariahilfer-strasse-wien-gruene-allee-2-abschnitt','Bäume für die Äußere Mariahilfer Straße: Grüne Allee wächst','In Rudolfsheim-Fünfhaus stehen die ersten neuen Bäume im zweiten Abschnitt der Äußeren Mariahilfer Straße. Insgesamt kommen 45 Bäume, breite Gehsteige und ein Radweg.','Die ersten **Bäume für die Äußere Mariahilfer Straße** sind gesetzt: Im zweiten Bauabschnitt im 15. Bezirk haben die Pflanzarbeiten begonnen. Die Bezirksvorstehung Rudolfsheim-Fünfhaus spricht von einem wichtigen Meilenstein für das Projekt, an dem seit dem Frühjahr 2026 gebaut wird. Am Ende sollen entlang des Abschnitts auf beiden Straßenseiten insgesamt 45 neue Bäume stehen.

## Bäume für die Äußere Mariahilfer Straße: das ist geplant

Der zweite Abschnitt reicht von der Clementinengasse bis zur Anschützgasse. Gemeinsam mit dem bestehenden Baumbestand soll so eine durchgehende grüne Allee entstehen. Die Pflanzbeete werden mit einer automatischen Bewässerung ausgestattet, damit die jungen Bäume auch in heißen, trockenen Sommern gut anwachsen.

Laut den Plänen der Stadt Wien wird die bestehende Grünfläche von rund 200 Quadratmetern deutlich vergrößert, insgesamt sind rund 1.300 Quadratmeter zusätzliche Begrünung vorgesehen. Regenwasser soll dort versickern und die Wurzeln der Bäume erreichen. Wie wichtig der richtige Boden und eine durchdachte Bewässerung für Pflanzen in Hitzeperioden sind, zeigt auch unser Ratgeber zum [trockenheitsresistenten Garten](/artikel/trockenheitsresistenter-garten-pflanzen-bewaesserung).

## Mehr Platz für Fußgänger und Radverkehr

Neben dem Grün verändert sich der Straßenraum spürbar:

- Die Gehsteige werden überwiegend vorgezogen und bis zu fünf Meter breit.
- Ein niedriger Randstein trennt Fahrbahn, Parkbuchten und Gehweg, ähnlich wie auf der Thaliastraße.
- Ein baulich getrennter Zwei-Richtungs-Radweg mit rund 700 Metern Länge entsteht.
- Die Äußere Mariahilfer Straße wird in diesem Bereich stadtauswärts zur Einbahn.
- Neue Sitzmöbel laden zum Verweilen ein.

Dazu kommen Elemente zur Abkühlung: Geplant sind ein Wasserspiel, 13 Nebelstelen und sechs Trinkhydranten. Die Clementinengasse wird zur verkehrsberuhigten Sackgasse mit zusätzlichem Baum, Sitzgelegenheiten und Wasserspiel. Auch beim Schwendermarkt sind mehr Grünflächen und Bäume vorgesehen. Die Stiegenanlage zwischen Sperrgasse und Karmeliterhofgasse wird barrierefreier umgebaut.

## Zeitplan: Fertigstellung vor dem Sommer 2027

Der zweite Abschnitt soll nach aktuellem Stand noch vor Beginn des Sommers 2027 fertig sein. Bereits umgebaut ist der erste Abschnitt zwischen Gürtel und Clementinengasse. Dort entstanden laut Stadt Wien über 600 Meter Radinfrastruktur, 19 neue Bäume und rund 800 Quadratmeter neuer Grünraum.

In den kommenden Jahren folgt ein dritter Abschnitt von der Anschützgasse bis zur Schloßallee. Ist auch dieser umgesetzt, wird die Äußere Mariahilfer Straße auf fast zwei Kilometern Länge durchgehend begrünt sein und eine durchgängige Radverbindung haben. Ein konkreter Termin für den letzten Abschnitt wurde noch nicht genannt.

## Hintergrund: Bürgerbefragung und Klimaanpassung

Dem Umbau ging im September 2023 eine Befragung der Anrainerinnen und Anrainer voraus. Zuletzt war die Straße in den 1990er-Jahren umgestaltet worden. Die Stadt setzt bei solchen Projekten verstärkt auf Bäume, Entsiegelung und Wasser, um dicht verbaute Grätzl im Sommer kühler zu machen. Wasser spielt dabei eine zentrale Rolle, wie auch die rund 1.800 [Trinkbrunnen in Wien](/artikel/trinkbrunnen-wien-winterpause-2026-hochstrahlbrunnen) zeigen.

Für Anrainer bedeutet die Baustelle bis zur Fertigstellung weiterhin Einschränkungen. Wer in der Gegend unterwegs ist, sollte die Umleitungen und geänderten Verkehrsführungen im Bereich zwischen Clementinengasse und Anschützgasse beachten.','bauen-wohnen','Garten','wien','news','Presseinfo Redaktion','/assets/img/artikel/baeume-aeussere-mariahilfer-strasse-wien-gruene-allee-2-abschnitt.webp','Bezirksvorstehung Rudolfsheim-Fünfhaus via 5min.at; Stadt Wien (Rathauskorrespondenz)','https://presse.wien.gv.at/presse/2025/03/24/sima-baurecht-klimafitte-aeussere-mahue-2-abschnitt-mit-700-m-radweg-und-45-neuen-baeumen','published','2026-11-24T06:46:00.000Z','2026-11-24T06:46:00.000Z','Bäume Äußere Mariahilfer Straße: Allee wächst','Bäume für die Äußere Mariahilfer Straße: Im 15. Bezirk sind die ersten von 45 neuen Bäumen gepflanzt. Was der 2. Abschnitt bringt und wann er fertig ist.','Bäume Äußere Mariahilfer Straße','["Bäume Äußere Mariahilfer Straße","Äußere MaHü","Rudolfsheim-Fünfhaus","grüne Allee Wien","Straßenbegrünung Wien","Äußere Mariahilfer Straße Umbau 2. Abschnitt","Zwei-Richtungs-Radweg Äußere MaHü","klimafitte Straße Wien 15. Bezirk"]','Bäume Äußere Mariahilfer Straße: neue Jungbäume in Pflanzbeeten im 15. Bezirk','Wide street view of a Viennese Gründerzeit street under construction in late autumn, workers planting young deciduous trees into new planting beds along a widened sidewalk, fresh soil, tree stakes, construction barriers, overcast November sky, Vienna 15th district atmosphere, no text, no logos, no readable signs','[{"q":"Wie viele Bäume kommen in die Äußere Mariahilfer Straße?","a":"Im zweiten Abschnitt zwischen Clementinengasse und Anschützgasse werden insgesamt 45 neue Bäume auf beiden Straßenseiten gepflanzt."},{"q":"Wann ist der zweite Abschnitt fertig?","a":"Die Fertigstellung ist voraussichtlich noch vor Beginn des Sommers 2027 geplant."},{"q":"Wie geht es danach weiter?","a":"In den kommenden Jahren folgt ein dritter Abschnitt von der Anschützgasse bis zur Schloßallee."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
